import torch, torch.nn as nn, math

class SinusoidalPE(nn.Module):
    def __init__(self, d_model, max_len=5000):
        super().__init__()
        pe = torch.zeros(max_len, d_model)
        pos = torch.arange(max_len).unsqueeze(1).float()
        div = torch.exp(torch.arange(0, d_model, 2).float()
                        * (-math.log(10000.0) / d_model))
        pe[:, 0::2] = torch.sin(pos * div)
        pe[:, 1::2] = torch.cos(pos * div)
        self.register_buffer('pe', pe)   # 固定常量：随模型保存但不训练
    def forward(self, x):               # x: (B, T, C)
        return x + self.pe[: x.size(1)]

class LearnedPE(nn.Module):
    def __init__(self, d_model, max_len=512):
        super().__init__()
        self.pe = nn.Embedding(max_len, d_model)  # 每个位置一个可学向量
    def forward(self, x):
        t = torch.arange(x.size(1), device=x.device)
        return x + self.pe(t).unsqueeze(0)
```

实现细节：`div` 预先算好 10000^(-2i/d) 一行的分母；`register_buffer` 保证固定编码不进优化器。对照验证：把 pe 的前几行画出来，应看到低维快振荡、高维慢振荡的条纹图。
